INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (11, 1, 72021, 0, 0, 1, "だからわたし、\n勇気を出して言ってみたんです！\nお友だちになりませんか、って。", 1, 10, 0, 72);
