INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (11, 1, 82013, 0, 0, 1, "その頃わたくしは、\nスカウトをお受けしておりました。\nミサト様いわく、わたくしには保育士の\n『天賦の才』があるそうで。", 1, 10, 0, 82);
INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (91, "", 82014, "", "", 0, "", 0, 0, "", 82);
INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (3, "", 82015, "", 0.2, 1, "sad_talk_surprise", "", 1, "", 82);
INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (21, "", 82016, "", "", "vo_asb", "vo_asb_0822", 0, 0, "", 82);
INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (11, 1, 82017, 0, 0, 1, "小さいお子様はともかく、動物さんに\n好かれる自覚はありますし……\n冒険者という仕事に不向きなことも、\n自認していますけれど……", 1, 10, 0, 82);
INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (91, "", 82018, "", "", 0, "", 0, 0, "", 82);
